def brute_force(arr: List[int]) -> int:
    # BFS, but neighbours are found by scanning the whole array for equal values at every pop.
    n = len(arr)
    dist = [-1] * n
    dist[0] = 0
    queue = deque([0])
    while queue:
        i = queue.popleft()
        if i == n - 1:
            return dist[i]
        nbrs = [j for j in range(n) if arr[j] == arr[i]] + [i - 1, i + 1]   # O(n) scan
        for j in nbrs:
            if 0 <= j < n and dist[j] == -1:
                dist[j] = dist[i] + 1
                queue.append(j)
    return dist[n - 1]

