def brute_force(n: int, k: int) -> str:
    # Walk all permutations in lexicographic order and stop at the k-th: O(n! * n).
    for i, perm in enumerate(permutations(range(1, n + 1)), 1):
        if i == k:
            return "".join(map(str, perm))
    return ""

